def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]

    first_my_d = -1
    first_opp_d = -1
    for i in range(n):
        if me[i] == 'D' and first_my_d == -1:
            first_my_d = i
        if opp[i] == 'D' and first_opp_d == -1:
            first_opp_d = i

    last_me, last_opp = history[-1]

    if first_opp_d != -1 and (first_my_d == -1 or first_opp_d <= first_my_d):
        if last_opp == 'D':
            streak = 0
            for i in range(n-1, -1, -1):
                if opp[i] == 'D':
                    streak += 1
                else:
                    break
            if streak >= 2:
                return 'D'
            if last_me == 'D':
                return 'C'
            if n >= 2 and history[-2][0] == 'D' and history[-1][0] == 'C':
                return 'C'
            return 'D'
        return 'C'

    if first_my_d != -1 and (first_opp_d == -1 or first_my_d < first_opp_d):
        retaliated = False
        for i in range(n - 1):
            if me[i] == 'D' and opp[i + 1] == 'D':
                retaliated = True
                break
        if retaliated:
            if last_opp == 'D':
                streak = 0
                for i in range(n-1, -1, -1):
                    if opp[i] == 'D':
                        streak += 1
                    else:
                        break
                if streak >= 2:
                    return 'D'
                if last_me == 'D':
                    return 'C'
                if n >= 2 and history[-2][0] == 'D' and history[-1][0] == 'C':
                    return 'C'
                return 'D'
            return 'C'
        else:
            if first_my_d == n - 1:
                return 'C'
            if last_opp == 'D':
                return 'D'
            return 'D'

    if n < 15:
        return 'C'
    if n == 15:
        return 'D'
    if n == 16:
        return 'C'
    return 'C'
